UPDATE role SET permissions = '{compliance.read,participant.read,genealogy.read,case.genealogy.read,order.read,late.manage,integration.read,plan.read,period.read,run.execute,run.review,trace.read,restatement.request,case.restatement.read,ledger.read,case.adjustment.read,case.adjustment.create,case.write_off.read,case.write_off.create,case.dispute.read,case.dispute.approve,credit.read,fx.manage}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Commission analyst';
