UPDATE role SET permissions = '{participant.read,participant.manage,genealogy.read,case.genealogy.read,case.genealogy.create,case.duplicate.read,case.duplicate.create,servicing.manage,order.read,period.read,run.review,trace.read,case.bank_detail.read,case.bank_detail.create,case.dispute.read,case.grievance.read,case.grievance.create,credit.read}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Support agent';
UPDATE role SET permissions = '{mapping.approve,compliance.read,snapshot.create,export,audit.read,market.signoff,participant.read,participant.terminate,participant_type.approve,agreement.publish,genealogy.read,case.genealogy.read,case.genealogy.approve,case.duplicate.read,case.duplicate.approve,order.read,plan.read,plan.approve,period.read,run.review,trace.read,restatement.request,case.restatement.read,guardrail.read,override.approve,ledger.read,payout.read,payout.hold,case.adjustment.read,case.write_off.read,case.bank_detail.read,case.bank_detail.approve,case.dispute.read,tax.read,case.grievance.read,case.grievance.create,case.grievance.approve,register.read,case.transfer.approve,legal_hold.manage}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Compliance officer';
UPDATE role SET permissions = '{compliance.read,audit.read,participant.unmask,participant.read,privacy.manage,legal_hold.manage}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'DPO';

-- market_references (0702) counting the V1-A keys to market: credit awards and redemptions, retention schedules.
CREATE OR REPLACE FUNCTION market_references(p_market_id uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$
  SELECT jsonb_build_object(
    'calendars', (SELECT count(*) FROM calendar WHERE market_id = p_market_id),
    'imports', (SELECT count(*) FROM import_batch WHERE market_id = p_market_id),
    'snapshots', (SELECT count(*) FROM compliance_report_snapshot WHERE market_id = p_market_id),
    'fact_participants', (SELECT count(*) FROM cpl_fact_participant WHERE market_id = p_market_id),
    'providers', (SELECT count(*) FROM provider_config WHERE market_id = p_market_id AND kind <> 'commerce'),
    'connectors', (SELECT count(*) FROM provider_config WHERE market_id = p_market_id AND kind = 'commerce'),
    'checklist_entries', (SELECT count(*) FROM market_checklist_entry WHERE market_id = p_market_id),
    'go_live_requests', (SELECT count(*) FROM market_go_live_request WHERE market_id = p_market_id),
    'cases', (SELECT count(*) FROM case_file WHERE market_id = p_market_id),
    'participants', (SELECT count(*) FROM participant WHERE market_id = p_market_id),
    'positions', (SELECT count(*) FROM position WHERE market_id = p_market_id),
    'orders', (SELECT count(*) FROM sales_order WHERE market_id = p_market_id),
    'product_volumes', (SELECT count(*) FROM product_volume_map WHERE market_id = p_market_id),
    'agreement_versions', (SELECT count(*) FROM agreement_version WHERE market_id = p_market_id),
    'plans', (SELECT count(*) FROM plan_market WHERE market_id = p_market_id),
    'ledger_accounts', (SELECT count(*) FROM ledger_account WHERE market_id = p_market_id),
    'journal_entries', (SELECT count(*) FROM journal_entry WHERE market_id = p_market_id),
    'gl_mappings', (SELECT count(*) FROM gl_account_map WHERE market_id = p_market_id),
    'journal_exports', (SELECT count(*) FROM journal_export WHERE market_id = p_market_id),
    'payout_batches', (SELECT count(*) FROM payout_batch WHERE market_id = p_market_id),
    'payout_holds', (SELECT count(*) FROM payout_hold WHERE market_id = p_market_id),
    'filings', (SELECT count(*) FROM plan_version_filing WHERE market_id = p_market_id),
    'migrations', (SELECT count(*) FROM migration WHERE market_id = p_market_id),
    'tax_form_generations', (SELECT count(*) FROM tax_form_generation WHERE market_id = p_market_id),
    'tax_forms', (SELECT count(*) FROM tax_form WHERE market_id = p_market_id),
    'credit_awards', (SELECT count(*) FROM credit_award WHERE market_id = p_market_id),
    'credit_redemptions', (SELECT count(*) FROM credit_redemption WHERE market_id = p_market_id),
    'retention_schedules', (SELECT count(*) FROM retention_schedule WHERE market_id = p_market_id),
    'grants', (SELECT count(*) FROM role_assignment WHERE p_market_id = ANY (market_ids))
            + (SELECT count(*) FROM role_grant_request WHERE p_market_id = ANY (market_ids)))
$$;

-- fx.max_rate_age_days (D-V1A-10) is approved by settings.approve like the money keys: the change-request backstops of
-- 0100/0107/0108 cover it (the TEN registry test pins both lists against approverPermission).
CREATE OR REPLACE FUNCTION money_setting_keys() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT ARRAY['money.rounding_mode', 'money.clawback_policy', 'payouts.market_policy',
               'payouts.bank_detail_cooling_off_hours', 'adjustments.policy', 'write_offs.policy', 'fx.max_rate_age_days']
$$;
CREATE OR REPLACE FUNCTION approval_setting_keys() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT ARRAY['money.rounding_mode', 'money.clawback_policy', 'genealogy.visibility_policy', 'payouts.market_policy',
               'payouts.bank_detail_cooling_off_hours', 'adjustments.policy', 'write_offs.policy', 'fx.max_rate_age_days',
               'privacy.policy', 'portal.customer_contact_visible', 'plan.filing_requirements']
$$;
